INSERT INTO mppt_parameter_map (id_mppt, id_parameter, parameter_type)
SELECT #{owner_id}, dp.id, #{parameter_type}
FROM device_parameters dp
JOIN device d ON d.id_device_group = dp.id_device_group
WHERE d.id = #{id_device}
	AND dp.status = 1
	AND dp.is_delete = 0
	AND dp.slug = #{parameter}
LIMIT 1

INSERT INTO string_parameter_map (id_string, id_parameter, parameter_type)
SELECT #{owner_id}, dp.id, #{parameter_type}
FROM device_parameters dp
JOIN device d ON d.id_device_group = dp.id_device_group
WHERE d.id = #{id_device}
	AND dp.status = 1
	AND dp.is_delete = 0
	AND dp.slug = #{parameter}
LIMIT 1
